STALE_KEY_ENGLISH = {"fault.permission_denied.action": "Open Settings, choose Privacy & Permissions, and set ‘What VOOL may do alone’ to change what governs this action.", "fault.tool_unavailable.action": "Open Settings, choose Privacy & Permissions, and set ‘What VOOL may do alone’, or choose a different approach.", "settings.email.none": "No email account yet, so VOOL cannot read or send email. To connect one, open Settings, choose Email, and press ‘Add email account’.", "skills.none_installed": "No skills yet. Ask VOOL in any chat: make me a skill that ...", "vcs.add.need_connect": "This calendar kind needs a connected account sign-in first, and there is none yet. Pick a different Source (for example ‘iCloud or another CalDAV server’, which needs only a server address), or connect that account’s sign-in on this computer first, then pick it here."}


def _messages(locale):
    return json.loads((CATALOGS_DIR / (locale + ".json")).read_text(encoding="utf-8"))["messages"]


def test_applied_rows_equal_the_handed_over_fixed_text():
    for key, locale, expected in APPLIED:
        got = _messages(locale).get(key)
        assert got == expected, (locale, key)


def test_de_new_keys_use_du_not_the_address_form():
    de = _messages("de")
    for key in DE_DU_KEYS:
        hits = ADDR_FORM.findall(de[key])
        if key in NON_ADDRESS_SIE and NON_ADDRESS_SIE[key] in de[key]:
            continue
        assert not hits, (key, hits)


def test_keys_pointers_use_the_current_group_title():
    for key, locale in POINTER_ROWS:
        msgs = _messages(locale)
        title = msgs["settings.group.keys.title"]
        assert title in msgs[key], (locale, key, title)


def test_the_retranslated_stale_keys_still_translate_this_english():
    en = _messages("en")
    for key, english in STALE_KEY_ENGLISH.items():
        assert en[key] == english, key
